const host = '10.1.0.105'; // CANDIDATO: MariaDB; confirmar IP del servicio DBS.
const port = 5000;
if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(host) || !Number.isInteger(port)) return [null,{payload:{evento:'CONFIG_INVALIDA'}}];
msg.host = host;
msg.port = port;
delete msg.payload; // El nodo TCP no escribe nada si payload está ausente.
return [msg,{payload:{evento:'INTENTO_CONEXION_TCP',host,port,envio_bytes:0,nota:'Una conexión abierta no confirma que el servicio sea DBS'}}];

delete msg.payload;
if (flow.get('envases_dbs_tcp_probe_conectado') !== true) {
    return [null,{payload:{evento:'YA_DESCONECTADO',envio_bytes:0,nota:'El servidor ya cerró la conexión; no hay socket activo que reiniciar'}}];
}
flow.set('envases_dbs_tcp_probe_conectado', false);
msg.reset = true;
return [msg,{payload:{evento:'CIERRE_SOLICITADO',envio_bytes:0}}];

const s=msg.status||{};
if (!s.fill && !s.text) {
    flow.set('envases_dbs_tcp_probe_conectado', false);
    return null; // Estado vacío del nodo, no es un fallo de red.
}
const conectado=s.fill==='green'&&s.shape==='dot';
flow.set('envases_dbs_tcp_probe_conectado', conectado);
let nota='Estado TCP sin diagnóstico específico';
if (conectado) nota='Conexión TCP abierta; identidad del servicio y protocolo sin verificar';
else if (s.fill==='grey'&&String(s.text).includes('disconnected')) nota='El extremo remoto cerró la conexión; sin petición no se esperan lecturas';
else if (s.fill==='red') nota='No se pudo mantener la conexión; revisar host, puerto y firewall';
else if (s.fill==='green'&&s.shape==='ring') nota='Conexión cerrada localmente';
return {payload:{evento:'ESTADO_TCP',color:s.fill||null,forma:s.shape||null,estado:s.text||null,nota}};

const text=String(msg.error&&msg.error.message||'Error TCP');
const code=(text.match(/\b(ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENETUNREACH|ENOTFOUND)\b/)||[])[1]||'ERROR_TCP';
return {payload:{evento:'ERROR_TCP',codigo:code,nota:'Comprobar host DBS, puerto 5000 y acceso desde el contenedor Node-RED'}};
